def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                candidates = [
                    grid[r][w - 1 - c],
                    grid[h - 1 - r][c],
                    grid[h - 1 - r][w - 1 - c],
                ]
                candidates = [x for x in candidates if x != 3]
                if candidates:
                    out[r][c] = max(set(candidates), key=candidates.count)
    return out
